mapper.delete:
DELETE FROM activity_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

mapper.select:
SELECT 
FROM activity_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

SELECT FROM activity_item
source_type = 'PERSONAL' AND owner_user_id = #{userId}
source_type = 'PUBLIC' AND owner_user_id IS NULL
AND (#{cityJson} = '[]' OR JSON_OVERLAPS(city, #{cityJson})) AND (#{locationJson} = '[]' OR JSON_OVERLAPS(location, #{locationJson})) AND (#{experienceGoalJson} = '[]' OR JSON_OVERLAPS(experience_goal, #{experienceGoalJson})) AND (#{companionJson} = '[]' OR JSON_OVERLAPS(companion, #{companionJson})) AND (#{budgetJson} = '[]' OR JSON_OVERLAPS(budget, #{budgetJson})) AND (#{activityTypeJson} = '[]' OR JSON_OVERLAPS(activity_type, #{activityTypeJson})) AND (#{styleJson} = '[]' OR JSON_OVERLAPS(style, #{styleJson})) AND (#{durationJson} = '[]' OR JSON_OVERLAPS(duration, #{durationJson})) AND (#{featureJson} = '[]' OR JSON_OVERLAPS(feature, #{featureJson})) AND (#{targetDateStart} IS NULL OR valid_from IS NULL OR valid_to IS NULL OR (valid_from <= #{targetDateEnd} AND valid_to >= #{targetDateStart})) AND (#{targetTimeStart} IS NULL OR valid_start_time IS NULL OR valid_end_time IS NULL OR (valid_start_time < #{targetTimeEnd} AND valid_end_time > #{targetTimeStart})) AND (#{excludeCityJson} = '[]' OR NOT JSON_OVERLAPS(city, #{excludeCityJson})) AND (#{excludeLocationJson} = '[]' OR NOT JSON_OVERLAPS(location, #{excludeLocationJson})) AND (#{excludeExperienceGoalJson} = '[]' OR NOT JSON_OVERLAPS(experience_goal, #{excludeExperienceGoalJson})) AND (#{excludeCompanionJson} = '[]' OR NOT JSON_OVERLAPS(companion, #{excludeCompanionJson})) AND (#{excludeBudgetJson} = '[]' OR NOT JSON_OVERLAPS(budget, #{excludeBudgetJson})) AND (#{excludeActivityTypeJson} = '[]' OR NOT JSON_OVERLAPS(activity_type, #{excludeActivityTypeJson})) AND (#{excludeStyleJson} = '[]' OR NOT JSON_OVERLAPS(style, #{excludeStyleJson})) AND (#{excludeDurationJson} = '[]' OR NOT JSON_OVERLAPS(duration, #{excludeDurationJson})) AND (#{excludeFeatureJson} = '[]' OR NOT JSON_OVERLAPS(feature, #{excludeFeatureJson}))
ORDER BY updated_at DESC LIMIT #{limit}
